function assignFirst(values) {
  let x = 0;
  [x] = values;
  return x;
}

function assignArguments() {
  return (arguments = 1);
}
assignArguments(41);

function pass(reader) {
  return reader(arguments = 7);
}
pass(function (value) { return value + 1; }, 41);

function pass(reader) {
  return reader(arguments());
}
var observed = '';
try {
  pass(function (value) { return value; }, 41);
} catch (e) {
  observed = e.name;
}
observed;

function* g(seed) {
  var observed = 0;
  yield 'ready';
  var C = class Box {
    static {
      Box.value = seed + 1;
      observed = Box.value + 1;
    }
  };
  return C.value + '|' + observed;
}
var iterator = g(40);
var first = iterator.next();
var second = iterator.next();
first.value + ':' + first.done + '|' + second.value + ':' + second.done;

